using System;using System.Collections;using System.Collections.Generic;using System.IO;using NUnit.Framework;using UnityEngine;using UnityEngine.TestTools;
public sealed partial class FlightMeasurementPlayMode {
 [Serializable]public class R16Probe{public bool enhanced;public float rate,dt,work,energy,requested,body;}
 [Serializable]public class R16Trial{public string id,launch,final;public float launchBodySpin,launchBudget,spent;public List<BreakRecord> actualBreaks=new List<BreakRecord>();public bool prepareClean,reducedPoseUnchanged;}
 [Serializable]public class R16Report{public string state="RUNNING",revision="r16-spin-stage1",method="Input curve probes and3Native naturally initialized601active-tick flights. Saved r15 final3runs are baseline; no3repeat/global suite. No C7/fun/owner-adoption verdict.";public List<R16Probe> probes=new List<R16Probe>();public List<R16Trial> trials=new List<R16Trial>();}
 [UnityTest]public IEnumerator R16SpinStage1(){Directory.CreateDirectory(Evidence);string file=Path.Combine(Evidence,"spin-stage1.json");Assert.That(File.Exists(file),Is.False);var report=new R16Report();Action save=()=>File.WriteAllText(file,JsonUtility.ToJson(report,true));save();var failed=new List<string>();
 foreach(bool enhanced in new[]{false,true})foreach(float rate in new[]{6f,12f,24f}){var t=RuntimeType("SpinCharge");var c=Activator.CreateInstance(t);t.GetField("ContinuousWork").SetValue(c,true);t.GetField("PowerScale").SetValue(c,28f/22);t.GetField("BodyLimit").SetValue(c,enhanced?40f:28f);t.GetField("EnhancedSpinR16").SetValue(c,enhanced);Call(c,"Begin");for(int i=0;i<601;i++){Call(c,"Add",rate/60,1f/60);Call(c,"Tick",1f/60);}report.probes.Add(new R16Probe{enhanced=enhanced,rate=rate,dt=1f/60,work=Convert.ToSingle(Property(c,"Work")),energy=Convert.ToSingle(Property(c,"Energy")),requested=Convert.ToSingle(Property(c,"SpinRps")),body=Convert.ToSingle(Property(c,"BodySpinRps"))});}save();Assert.That(report.probes[1].work,Is.EqualTo(report.probes[0].work));Assert.That(report.probes[4].work,Is.GreaterThan(report.probes[3].work));Assert.That(report.probes[5].work,Is.GreaterThan(report.probes[4].work));Assert.That(report.probes[4].body,Is.GreaterThan(report.probes[3].body));
 // Two short same-clock setup render fixtures; not additional flight/reach claims.
 foreach(bool legacy in new[]{true,false}){StaticField(gameType,"ReviewLegacySpinR16",legacy);yield return NewRetrySubject(false,true,true,true,true,true,true);Call(current,"Configure",JsonUtility.ToJson(new InputSpec{angle=35,power=100,direction=1,upgradeLevel=3}));Call(current,"BeginAim","");Call(current,"PreviewLaunch",JsonUtility.ToJson(new Aim{angle=35,power=100,direction=1}));Call(current,"BeginSpinCharge","");for(int i=0;i<601;i++){Call(current,"AddSpinWork",JsonUtility.ToJson(new Work{direction=1,distance=6f/60,seconds=1f/60}));Call(current,"Tick",1f/60);}for(int k=0;k<8;k++){Call(current,"Tick",1f/60);CaptureRoute(legacy?"legacy-charge":"new-charge","f"+k);}Call(current,"SetReducedMotion","1");Call(current,"Tick",0f);CaptureRoute(legacy?"legacy-charge":"new-charge","reduced");Call(current,"ShutdownReviewPhysics");current=null;yield return null;yield return null;}
 StaticField(gameType,"ReviewLegacySpinR16",false);
 foreach(var spec in new[]{new R12Spec{id="r16-standard12",angle=12,level=0,rate=2},new R12Spec{id="r16-floor16",angle=16,level=0,rate=2},new R12Spec{id="r16-fast35",angle=35}}){yield return NewRetrySubject(false,true,true,true,true,true,true);StartRouteChargeR11(spec.angle,spec.level,spec.rate,spec.direction);var sim=Property(current,"ReviewSimulation");var body=(Rigidbody)Property(sim,"Body");var row=new R16Trial{id=spec.id,launch=JsonUtility.ToJson(Field(State(current),"launchReceipt")),launchBodySpin=body.angularVelocity.magnitude/(Mathf.PI*2),launchBudget=Convert.ToSingle(Property(sim,"RotorCapacity"))};report.trials.Add(row);bool capture=false;
 for(int tick=0;tick<11000&&!(bool)Property(current,"Finished");tick++){Call(current,"Tick",1f/60);var st=State(current);if(!capture&&F(st,"distance")>20){CaptureRoute(spec.id,"flight");string before=(string)Call(sim,"LaunchBodyReceipt");Call(current,"SetReducedMotion","1");Call(current,"Tick",0f);CaptureRoute(spec.id,"flight-reduced");row.reducedPoseUnchanged=before==(string)Call(sim,"LaunchBodyReceipt");Call(current,"SetReducedMotion","0");capture=true;}}
 row.final=JsonUtility.ToJson(State(current));row.spent=Convert.ToSingle(Property(sim,"OverdriveSpent"));foreach(var e in (IEnumerable)Field(sim,"BreakEvents"))row.actualBreaks.Add(new BreakRecord{id=(string)Field(e,"id"),material=(string)Field(e,"material"),secondary=(bool)Field(e,"secondary"),time=F(e,"time"),position=(Vector3)Field(e,"position")});CaptureRoute(spec.id,"result");save();var final=State(current);if(!(bool)Property(current,"Finished")||!String.IsNullOrEmpty((string)Field(final,"physicsFault")))failed.Add(spec.id+":"+(string)Field(final,"physicsFault"));float budget=row.launchBudget+F(final,"reclaimedRotorJ"),remaining=F(final,"rotorRemaining");Assert.That(float.IsFinite(remaining)&&remaining>=0,Is.True);Assert.That(Mathf.Abs(budget-row.spent-remaining),Is.LessThan(Mathf.Max(.1f,budget*1e-5f)),"finite rotor ledger");Assert.That(row.reducedPoseUnchanged,Is.True);Call(current,"Prepare","");row.prepareClean=F(State(current),"time")==0&&F(State(current),"chargeWork")==0&&Convert.ToInt32(Field(State(current),"destructionEvent"))==0;save();Assert.That(row.prepareClean,Is.True);Call(current,"ShutdownReviewPhysics");current=null;yield return null;yield return null;}
 report.state=failed.Count==0?"COMPLETED_NO_OBSERVED_FAULT":"COMPLETED_WITH_FAULT";save();Assert.That(failed,Is.Empty,String.Join(",",failed));}
}
